// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Shared test utilities
const mockCart = {
  items: [{ id: '1', name: 'Bronze Shield', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-OLYMPUS-001' }),
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

const validShipping = {
  street: '123 Mount Olympus',
  city: 'Athens',
  state: 'CA',
  zip: '90210',
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Zeus Thunderer',
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/bronze shield/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert: Confirmation
    expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    expect(screen.getByText('ORD-OLYMPUS-001')).toBeInTheDocument();
    expect(onComplete).toHaveBeenCalledWith('ORD-OLYMPUS-001');
  });
});

describe('Checkout - Validation', () => {
  it('displays error when ZIP format is invalid', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByLabelText(/zip/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    mockCart.items = [];
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure gracefully', async () => {
    mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... complete flow to review, click place order
    expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
